// Title: How to add a text file attachment to a PDF generated with Aspose.Cells for .NET (PdfSaveOptions.Attachments limitation)
// Common Searches: asp.net add a text file attachment to a PDF created with aspose.cells | c# aspose.cells pdfsaveoptions attachments feature not working | how to embed a text document in a PDF generated by aspose.cells | aspose.cells generate PDF with attached files using pdfsaveoptions | pdf attachment support in aspose.cells for .NET | workbook to pdf with embedded attachment using aspose.cells c#
// Tags: aspose.cells pdf attachment limitation | pdfsaveoptions attachments c# | embed text file in pdf using aspose.cells | c# workbook to pdf with attachment | aspose.cells generate pdf with embedded files

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, writes a value to cell A1, generates a temporary text file, configures PdfSaveOptions (highlighting that the Attachments collection is not supported in Aspose.Cells), and saves the workbook as a PDF. It illustrates the current limitation of adding file attachments to PDFs with Aspose.Cells for .NET.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook (create rule)
            Workbook workbook = new Workbook();

            // Add sample data to the first worksheet
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Hello Aspose.Cells!");

            // Prepare a temporary text file (optional, not attached to PDF)
            string attachmentPath = Path.Combine(Path.GetTempPath(), "SampleAttachment.txt");
            File.WriteAllText(attachmentPath, "This is the content of the attached text file.");

            // Configure PDF save options (no attachment support in Aspose.Cells)
            PdfSaveOptions pdfOptions = new PdfSaveOptions();

            // Define output PDF path
            string outputPdf = Path.Combine(Directory.GetCurrentDirectory(), "OutputWithAttachment.pdf");

            // Save the workbook as PDF
            workbook.Save(outputPdf, pdfOptions);

            Console.WriteLine($"PDF saved successfully to: {outputPdf}");
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
